'use strict';
// #1864: a PDF over 25 MiB is read page range by page range instead of being skipped, up to page and text
// ceilings that end in a stated partial result. #1865: a page left incomplete after the first pass is
// retried alone through the local OCR worker, once, and the result is merged or the reason recorded.
// Every PDF here is generated by this file (synthetic text, no real documents); OCR and Docling are fakes.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const documents = require('./documents.cjs');
const documentSources = require('./document-sources.cjs');
const native = require('./documents-native.cjs');
const sourceLimits = require('./source-limits.cjs');

const MiB = 1024 * 1024;
const testDir = fs.mkdtempSync(path.join(os.tmpdir(), 'noevia-1864-'));
test.after(() => fs.rmSync(testDir, { recursive: true, force: true }));

/** A synthetic PDF: `pages` pages, page n saying `SYN-PAGE-<n>` (or nothing when `text(n)` is ''), plus an
 *  unreferenced stream of `padding` bytes so the file can be made any size without more pages. */
function syntheticPdf({ pages, padding = 0, text = (n) => `SYN-PAGE-${n} synthetic body line for page ${n}` }) {
  const objects = [];
  const add = (body) => { objects.push(body); return objects.length; };
  const catalog = add(null), pagesObj = add(null), font = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  const kids = [];
  for (let n = 1; n <= pages; n++) {
    const words = text(n);
    const content = words ? `BT /F1 12 Tf 72 720 Td (${words}) Tj ET` : '';
    const stream = add(`<< /Length ${Buffer.byteLength(content)} >>\nstream\n${content}\nendstream`);
    kids.push(add(`<< /Type /Page /Parent ${pagesObj} 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${stream} 0 R >>`));
  }
  objects[catalog - 1] = `<< /Type /Catalog /Pages ${pagesObj} 0 R >>`;
  objects[pagesObj - 1] = `<< /Type /Pages /Kids [${kids.map((k) => `${k} 0 R`).join(' ')}] /Count ${pages} >>`;
  const parts = [Buffer.from('%PDF-1.4\n')];
  let size = parts[0].length;
  const offsets = [];
  const push = (buf) => { parts.push(buf); size += buf.length; };
  objects.forEach((body, i) => { offsets.push(size); push(Buffer.from(`${i + 1} 0 obj\n${body}\nendobj\n`)); });
  let count = objects.length;
  if (padding > 0) {
    count += 1;
    offsets.push(size);
    push(Buffer.from(`${count} 0 obj\n<< /Length ${padding} >>\nstream\n`));
    push(Buffer.alloc(padding, 0x41));
    push(Buffer.from('\nendstream\nendobj\n'));
  }
  const xref = size;
  push(Buffer.from(`xref\n0 ${count + 1}\n0000000000 65535 f \n${offsets.map((o) => String(o).padStart(10, '0') + ' 00000 n \n').join('')}trailer\n<< /Size ${count + 1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`));
  return Buffer.concat(parts);
}

const big = syntheticPdf({ pages: 60, padding: 26 * MiB });
const nativeOnly = (extra = {}) => ({ doclingEnabled: false, ocrEnabled: false, waits: [0, 0], ...extra });
/** readInWorker, counting the ranges it is asked for. */
function countingReader() {
  const calls = [];
  return { calls, readPages: (bytes, options) => { calls.push({ first: options.firstPage || 1, cap: options.pageCap }); return native.readInWorker(bytes, options); } };
}

test('the synthetic large PDF is over the old 25 MiB gate', () => {
  assert.ok(big.length > 26 * MiB);
  assert.ok(big.length > documents.WHOLE_BYTES);
});

test('#1864: a PDF over 25 MiB is read in page ranges and fully indexed, with bounded memory', async () => {
  const reader = countingReader();
  const before = process.memoryUsage.rss();
  let peak = before;
  const watch = setInterval(() => { peak = Math.max(peak, process.memoryUsage.rss()); }, 20);
  let out;
  try { out = await documents.extractDocumentText('large.pdf', big, nativeOnly({ readPages: reader.readPages, env: {} })); }
  finally { clearInterval(watch); }
  assert.equal(out.pages, 60);
  assert.equal(out.pageTexts.length, 60);
  assert.equal(out.state, 'ready');
  assert.equal(out.stoppedAt, undefined);
  for (const n of [1, 25, 26, 60]) assert.ok(out.text.includes(`SYN-PAGE-${n} `), `page ${n} text is in the indexed text`);
  assert.deepEqual(out.pageTexts.map((p) => p.number), Array.from({ length: 60 }, (_, i) => i + 1));
  // Ranges of the default 25 pages: 1-25, 26-50, 51-60. Never one whole-document read.
  assert.deepEqual(reader.calls, [{ first: 1, cap: 25 }, { first: 26, cap: 25 }, { first: 51, cap: 10 }]);
  assert.equal(out.completion, documents.COMPLETION);
  // One range in flight at a time: the growth is the file and one reader's copy, not a copy per range.
  const growthMiB = (peak - before) / MiB;
  console.log(`[#1864 memory] ${Math.round(big.length / MiB)} MiB PDF, 60 pages in 3 ranges: peak RSS growth ${growthMiB.toFixed(0)} MiB`);
  assert.ok(growthMiB < 3 * (big.length / MiB) + 300, `RSS growth ${growthMiB.toFixed(0)} MiB stays bounded`);
});

test('#1864: past the page ceiling the document is partial, "stopped at page N (page limit)", never skipped', async () => {
  const out = await documents.extractDocumentText('large.pdf', big, nativeOnly({ env: { PROJECT_DOCUMENT_PAGE_LIMIT: '30' } }));
  assert.equal(out.pages, 60);
  assert.equal(out.pageTexts.length, 30);
  assert.equal(out.state, 'partial');
  assert.deepEqual(out.stoppedAt, { page: 30, limit: 'pages' });
  assert.ok(out.text.includes('SYN-PAGE-30 ') && !out.text.includes('SYN-PAGE-31 '));
});

test('#1864: past the text ceiling the document stops at the page that reached it', async () => {
  const out = await documents.extractDocumentText('large.pdf', big, nativeOnly({ env: { PROJECT_DOCUMENT_TEXT_LIMIT: '2000', PROJECT_DOCUMENT_RANGE_PAGES: '10' } }));
  assert.equal(out.state, 'partial');
  assert.equal(out.stoppedAt.limit, 'text');
  assert.ok(out.stoppedAt.page >= 10 && out.stoppedAt.page < 60);
  assert.ok(out.pageTexts.reduce((n, p) => n + p.text.length, 0) <= 2000 + 200);
});

test('#1864: the limits follow the source-limits pattern (env overrides, bad values ignored)', () => {
  assert.deepEqual(sourceLimits.documentLimits({}), { readBytes: 96 * MiB, pages: 1000, text: 8_000_000, rangePages: 25, syncOcrPages: 40 });
  assert.deepEqual(sourceLimits.documentLimits({ PROJECT_DOCUMENT_READ_BYTES: '1048576', PROJECT_DOCUMENT_PAGE_LIMIT: '-3', PROJECT_DOCUMENT_TEXT_LIMIT: 'x', PROJECT_DOCUMENT_RANGE_PAGES: '5000', PROJECT_SYNC_OCR_PAGES: '7' }),
    { readBytes: MiB, pages: 1000, text: 8_000_000, rangePages: 200, syncOcrPages: 7 });
  // #1871: within the PDF reader's pending-bytes bound, and still far above the old 25 MiB gate.
  assert.ok(sourceLimits.documentLimits({}).readBytes <= native.MAX_PENDING_BYTES);
  assert.ok(sourceLimits.documentLimits({}).readBytes > 3 * 25 * MiB);
});

// A fake Docling worker: `pages` total, page text SYN-DOC-<n>, honouring X-Document-Pages like the worker
// from #1864 on (or ignoring it, like one from before).
function fakeDocling({ total, ranges = true, degraded = [] }) {
  const calls = [];
  const page = (n) => degraded.includes(n)
    ? { number: n, text: `native layer ${n}`, status: 'degraded', method: 'pdfium', reason: 'native-fallback', truncated: false }
    : { number: n, text: `SYN-DOC-${n}`, status: 'native', method: 'docling', truncated: false };
  const extractDocument = async (_name, bytes, options = {}) => {
    calls.push(options.pages ? options.pages.join('-') : 'whole');
    const [first, last] = ranges && options.pages ? options.pages : [1, Math.min(total, 300)];
    const pages = [];
    for (let n = first; n <= Math.min(last, total); n++) pages.push(page(n));
    return { pages, total, truncatedPages: total > last };
  };
  return { calls, extractDocument, rangesSupported: async () => ranges };
}
const docling = (fake, extra = {}) => ({ doclingEnabled: true, ocrEnabled: false, figures: false, waits: [0, 0], extractDocument: fake.extractDocument, rangesSupported: fake.rangesSupported, env: {}, ...extra });

test('#1864 (Docling): a large PDF is never sent whole; it is read range by range', async () => {
  const fake = fakeDocling({ total: 60 });
  const out = await documents.extractDocumentText('large.pdf', big, docling(fake));
  assert.deepEqual(fake.calls, ['1-25', '26-50', '51-60']);
  assert.equal(out.state, 'ready');
  assert.equal(out.pageTexts.length, 60);
  assert.ok(out.text.includes('SYN-DOC-60'));
});

test('#1864 (Docling): a worker without page ranges is never sent a large PDF; it is read here, range by range', async () => {
  const fake = fakeDocling({ total: 60, ranges: false });
  const reader = countingReader();
  const out = await documents.extractDocumentText('large.pdf', big, docling(fake, { readPages: reader.readPages }));
  assert.deepEqual(fake.calls, []);
  assert.deepEqual(reader.calls, [{ first: 1, cap: 25 }, { first: 26, cap: 25 }, { first: 51, cap: 10 }]);
  assert.equal(out.state, 'ready');
  assert.equal(out.pageTexts.length, 60);
  assert.ok(out.pageTexts.every((p) => p.method === 'native'));
  assert.ok(out.text.includes('SYN-PAGE-60 '));
  assert.equal(out.completion, documents.COMPLETION);
});

test('#1864 (Docling): a small PDF is read whole as before, and pages past 300 follow in ranges', async () => {
  const long = syntheticPdf({ pages: 340 });
  const fake = fakeDocling({ total: 340 });
  const out = await documents.extractDocumentText('long.pdf', long, docling(fake));
  assert.deepEqual(fake.calls, ['whole', '301-325', '326-340']);
  assert.equal(out.pageTexts.length, 340);
  assert.equal(out.state, 'ready');
  // A worker without ranges (today's sidecars): the first window comes from Docling as always, and the
  // pages past 300 are read here instead of the document stopping at 300.
  const old = fakeDocling({ total: 340, ranges: false });
  const reader = countingReader();
  const rest = await documents.extractDocumentText('long.pdf', long, docling(old, { readPages: reader.readPages }));
  assert.deepEqual(old.calls, ['whole']);
  assert.deepEqual(reader.calls, [{ first: 301, cap: 25 }, { first: 326, cap: 15 }]);
  assert.equal(rest.state, 'ready');
  assert.equal(rest.pageTexts.length, 340);
  assert.equal(rest.pageTexts[299].method, 'docling');
  assert.equal(rest.pageTexts[300].method, 'native');
  assert.ok(rest.text.length > 0 && rest.pageTexts[339].text.includes('SYN-PAGE-340 '));
  assert.equal(rest.stoppedAt, undefined);
});

test('#1864: OCR is never sent a PDF larger than it accepts; the pages say why', async () => {
  let asked = 0;
  const extractPages = async () => { asked++; return []; };
  const first = { text: '[Page 1]\nx', pages: 2, state: 'partial', truncated: false, retryable: false,
    pageTexts: [{ number: 1, text: 'x', status: 'native', method: 'native' }, { number: 2, text: '', status: 'ocr-needed', method: 'native' }] };
  const out = await documents.completeDocument('large.pdf', big, first, nativeOnly({ ocrEnabled: true, extractPages, env: {} }));
  assert.equal(asked, 0);
  assert.deepEqual(out.pageTexts[1].retry, { outcome: 'failed', error: 'the PDF is larger than the OCR service accepts (25 MB)' });
  assert.equal(out.state, 'partial');
  assert.equal(out.completion, documents.COMPLETION);
});

test('#1864 (Docling): an extractor error part-way stops with the page and the reason, keeping what was read', async () => {
  const fake = fakeDocling({ total: 60 });
  const extractDocument = async (name, bytes, options) => {
    if (options?.pages?.[0] === 26) throw new Error('This document took longer than its processing time limit to read');
    return fake.extractDocument(name, bytes, options);
  };
  const out = await documents.extractDocumentText('large.pdf', big, docling(fake, { extractDocument }));
  assert.equal(out.pageTexts.length, 25);
  assert.equal(out.state, 'partial');
  assert.equal(out.stoppedAt.page, 25);
  assert.equal(out.stoppedAt.limit, 'error');
  assert.equal(out.completion, documents.COMPLETION, 'a timeout is final for this version, not retried every sync');
});

// A fake OCR worker. `answer(page, options)` gives the text (or throws).
function fakeOcr(answer) {
  const calls = [];
  const extractPages = async (_bytes, pages, options = {}) => {
    calls.push({ pages: [...pages], dpi: options.dpi });
    return pages.map((n) => ({ number: n, text: answer(n, options) }));
  };
  return { calls, extractPages };
}

test('#1865: a degraded page is retried alone through OCR at a higher DPI and its text is merged', async () => {
  const fake = fakeDocling({ total: 3, degraded: [1] });
  const ocr = fakeOcr((n) => (n === 1 ? 'FORM FIELD SYN-VALUE 1234.56' : ''));
  const out = await documents.extractDocumentText('form.pdf', syntheticPdf({ pages: 3 }), docling(fake, { ocrEnabled: true, extractPages: ocr.extractPages }));
  assert.deepEqual(ocr.calls, [{ pages: [1], dpi: documents.RETRY_DPI }]);
  const p1 = out.pageTexts[0];
  assert.equal(p1.status, 'ocr');
  assert.equal(p1.reason, undefined);
  assert.deepEqual(p1.retry, { outcome: 'recovered', dpi: 400, from: 'degraded' });
  assert.match(p1.text, /native layer 1\n\[OCR transcription — verify numbers against original\]\nFORM FIELD SYN-VALUE 1234\.56/);
  assert.ok(out.text.includes('SYN-VALUE 1234.56'));
  assert.equal(out.state, 'ready');
});

test('#1865: an OCR retry that fails leaves the page degraded with the reason, and is not repeated', async () => {
  const fake = fakeDocling({ total: 3, degraded: [2] });
  const ocr = fakeOcr(() => { throw new Error('OCR failed or reached its processing limit; refresh to retry.'); });
  const out = await documents.extractDocumentText('form.pdf', syntheticPdf({ pages: 3 }), docling(fake, { ocrEnabled: true, extractPages: ocr.extractPages }));
  assert.equal(ocr.calls.length, 1);
  assert.equal(out.state, 'partial');
  assert.equal(out.pageTexts[1].status, 'degraded');
  assert.equal(out.pageTexts[1].retry.outcome, 'failed');
  assert.equal(out.pageTexts[1].retry.again, undefined, 'a page-level failure is final');
  assert.equal(out.completion, documents.COMPLETION);
  // Bounded: a completed result is not retried again.
  const again = await documents.completeDocument('form.pdf', Buffer.from('x'), out, docling(fake, { ocrEnabled: true, extractPages: ocr.extractPages }));
  assert.equal(again, out);
  assert.equal(ocr.calls.length, 1);
  // The source record and its problem line carry the outcome.
  const file = { name: 'form.pdf', document: { state: out.state, pages: 3, pageStatus: out.pageTexts.map((p) => ({ number: p.number, status: p.status, ...(p.reason ? { reason: p.reason } : {}), ...(p.retry ? { retry: { outcome: p.retry.outcome, error: p.retry.error } } : {}) })) } };
  assert.match(documentSources.problem(file), /incomplete pages 2 \(degraded: native-fallback\); pages 2: OCR retry failed: OCR failed or reached its processing limit/);
  assert.deepEqual(documentSources.notes(file), [{ id: 'ocrRetryFailed', params: { pages: '2', reason: 'OCR failed or reached its processing limit; refresh to retry.' } }]);
});

test('#1865: a busy OCR worker is asked again within bounds, then on later reads, at most RETRY_ATTEMPTS times', async () => {
  const fake = fakeDocling({ total: 2, degraded: [1] });
  let asked = 0;
  const extractPages = async () => { asked++; throw Object.assign(new Error('OCR is busy; refresh to retry.'), { status: 503 }); };
  const deps = docling(fake, { ocrEnabled: true, extractPages });
  let out = await documents.extractDocumentText('form.pdf', syntheticPdf({ pages: 2 }), deps);
  assert.equal(asked, 3, 'the first ask and two bounded waits');
  assert.equal(out.pageTexts[0].retry.again, true);
  assert.equal(out.completion, undefined, 'a passing failure leaves the result open for a later read');
  for (let read = 0; read < 5; read++) out = await documents.completeDocument('form.pdf', Buffer.from('x'), out, deps);
  assert.equal(out.pageTexts[0].retry.attempts, documents.RETRY_ATTEMPTS);
  assert.equal(out.pageTexts[0].retry.again, undefined);
  assert.equal(out.completion, documents.COMPLETION);
  assert.equal(asked, 3 * documents.RETRY_ATTEMPTS, 'never more than RETRY_ATTEMPTS passes');
});

test('#1865: without an OCR worker the page says the retry is unavailable; past the cap pages say they were not retried', async () => {
  const none = await documents.extractDocumentText('form.pdf', syntheticPdf({ pages: 2 }), docling(fakeDocling({ total: 2, degraded: [2] })));
  assert.deepEqual(none.pageTexts[1].retry, { outcome: 'unavailable' });
  const many = Array.from({ length: 25 }, (_, i) => i + 1);
  const ocr = fakeOcr(() => '');
  const capped = await documents.extractDocumentText('form.pdf', syntheticPdf({ pages: 2 }), docling(fakeDocling({ total: 25, degraded: many }), { ocrEnabled: true, extractPages: ocr.extractPages }));
  assert.deepEqual(ocr.calls.map((c) => c.pages.length), [3, 3, 3, 3, 3, 3, 2], "#1882: RETRY_BATCH (3) pages per request, RETRY_PAGE_CAP in all");
  assert.equal(capped.pageTexts.filter((p) => p.retry?.outcome === 'empty').length, documents.RETRY_PAGE_CAP);
  assert.equal(capped.pageTexts.filter((p) => p.retry?.outcome === 'skipped').length, 25 - documents.RETRY_PAGE_CAP);
});

test('#1871: a page the first pass already sent to OCR is not retried at the same resolution (until #1867)', async () => {
  const scanned = fs.readFileSync(path.join(__dirname, 'fixtures/documents/scanned.pdf'));
  const ocr = fakeOcr(() => '');
  const out = await documents.extractDocumentText('scanned.pdf', scanned, nativeOnly({ ocrEnabled: true, extractPages: ocr.extractPages, env: {} }));
  assert.deepEqual(ocr.calls, [{ pages: [1], dpi: undefined }], 'one OCR pass, no second identical one');
  assert.equal(out.pageTexts[0].status, 'unreadable');
  assert.equal(out.pageTexts[0].retry, undefined);
  assert.equal(out.completion, documents.COMPLETION);
  // A result stored before the mark existed: an unreadable pdf.js page with OCR on was OCRed already.
  const { ocrSent, ...old } = out.pageTexts[0];
  const again = await documents.completeDocument('scanned.pdf', scanned, { ...out, completion: undefined, pageTexts: [old] }, nativeOnly({ ocrEnabled: true, extractPages: ocr.extractPages, env: {} }));
  assert.equal(ocr.calls.length, 1);
  assert.equal(again.pageTexts[0].retry, undefined);
});

test('#1865 (native, real pdf.js): a page the first pass could not send to OCR is retried and merged', async () => {
  const scanned = fs.readFileSync(path.join(__dirname, 'fixtures/documents/scanned.pdf'));
  // The first pass without OCR leaves the scanned page 'ocr-needed'; with OCR on later, it is retried.
  const first = await documents.extractDocumentText('scanned.pdf', scanned, nativeOnly({ env: {} }));
  const ocr = fakeOcr(() => 'SCAN-P2 INV-2042 total 34.95');
  const out = await documents.completeDocument('scanned.pdf', scanned, { ...first, completion: undefined, pageTexts: first.pageTexts.map(({ retry, ...p }) => p) },
    nativeOnly({ ocrEnabled: true, extractPages: ocr.extractPages, env: {} }));
  assert.deepEqual(ocr.calls, [{ pages: [1], dpi: 400 }]);
  assert.equal(out.pageTexts[0].status, 'ocr');
  assert.equal(out.pageTexts[0].retry.outcome, 'recovered');
  assert.equal(out.state, 'ready');
  assert.equal(out.error, undefined, 'the "no text" error is gone once a retry found text');
  assert.ok(out.text.includes('INV-2042'));
});

test('default behaviour for a normal PDF is unchanged: same text, state and extractor version', async () => {
  const text = fs.readFileSync(path.join(__dirname, 'fixtures/documents/text.pdf'));
  const reader = countingReader();
  const out = await documents.extractDocumentText('text.pdf', text, nativeOnly({ readPages: reader.readPages, env: {} }));
  assert.deepEqual(reader.calls, [{ first: 1, cap: documents.PAGE_CAP }], 'one whole read, as before');
  assert.equal(out.state, 'ready');
  assert.equal(out.stoppedAt, undefined);
  assert.ok(out.pageTexts.every((p) => p.retry === undefined));
  assert.match(out.text, /^\[Page 1\]\n.*TEXT-P1/s);
  // The cache key is untouched, so no stored document is read again because of this change.
  const docling = require('./docling.cjs');
  assert.equal(docling.VERSION, 'docling-2.129-layout-tableformer-tesseract-v3-native-fallback');
  const workers = require('./document-workers.cjs');
  workers.useMachines(() => null);
  const saved = { OCR_BASE_URL: process.env.OCR_BASE_URL, DOCLING_BASE_URL: process.env.DOCLING_BASE_URL };
  try {
    delete process.env.OCR_BASE_URL; delete process.env.DOCLING_BASE_URL;
    assert.equal(documents.EXTRACTOR_VERSION, 'native-pages-v2');
    process.env.DOCLING_BASE_URL = 'http://docling.invalid:8031';
    assert.equal(documents.EXTRACTOR_VERSION, 'docling-pages-v1:' + docling.VERSION);
  } finally {
    for (const [k, v] of Object.entries(saved)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; }
  }
});

test('#1864/#1865: a result stored before this change gets the pass once (targeted re-read, no version change)', async () => {
  const workspace = { dir: path.join(testDir, 'ws-targeted'), assertActive: () => {} };
  const bytes = syntheticPdf({ pages: 3 });
  const fake = fakeDocling({ total: 3, degraded: [1] });
  const ocr = fakeOcr(() => 'SYN-RECOVERED 77');
  const realExtract = documents.extractDocumentText, realComplete = documents.completeDocument;
  let extracts = 0;
  // A stored result as the code before this change wrote it: no marker, page 1 degraded.
  documents.extractDocumentText = async (name, b) => { extracts++; const r = await realExtract(name, b, docling(fake)); const { completion, ...old } = r; old.pageTexts = old.pageTexts.map(({ retry, ...p }) => p); return old; };
  documents.completeDocument = (name, b, out) => realComplete(name, b, out, docling(fake, { ocrEnabled: true, extractPages: ocr.extractPages }));
  try {
    const first = await documentSources.ingest(workspace, 'p1', 'Tax/form.pdf', bytes, null);
    assert.equal(first.document.state, 'partial');
    assert.equal(ocr.calls.length, 0);
    // The next read finds the stored result, does not extract again, and runs the pass once.
    const second = await documentSources.ingest(workspace, 'p1', 'Tax/form.pdf', bytes, first);
    assert.equal(extracts, 1);
    assert.equal(ocr.calls.length, 1);
    assert.equal(second.document.version, first.document.version, 'same version: nothing else is re-read');
    assert.equal(second.document.state, 'ready');
    assert.deepEqual(second.document.pageStatus[0], { number: 1, status: 'ocr', retry: { outcome: 'recovered' } });
    assert.ok(second.content.includes('SYN-RECOVERED 77'));
    const third = await documentSources.ingest(workspace, 'p1', 'Tax/form.pdf', bytes, second);
    assert.equal(ocr.calls.length, 1, 'bounded: once per stored result');
    assert.equal(third.content, second.content);
    assert.match(documentSources.readPages(workspace, 'p1', third, 1, 1).text, /SYN-RECOVERED 77/);
  } finally { documents.extractDocumentText = realExtract; documents.completeDocument = realComplete; }
});

test('#1864: the source record and its problem line say where reading stopped', async () => {
  const workspace = { dir: path.join(testDir, 'ws-stopped'), assertActive: () => {} };
  const realExtract = documents.extractDocumentText;
  documents.extractDocumentText = (name, b) => realExtract(name, b, nativeOnly({ env: { PROJECT_DOCUMENT_PAGE_LIMIT: '30' } }));
  try {
    const file = await documentSources.ingest(workspace, 'p1', 'Finance/large.pdf', big, null);
    assert.equal(file.document.state, 'partial');
    assert.deepEqual(file.document.stoppedAt, { page: 30, limit: 'pages' });
    assert.equal(file.document.bytes, big.length);
    assert.match(documentSources.problem(file), /partial; 60 pages; .*stopped at page 30 \(page limit\)/);
    assert.deepEqual(documentSources.problemNotes(file).notes, [{ id: 'stoppedAtPage', params: { page: 30, limit: 'pages' } }]);
    assert.doesNotMatch(documentSources.problemNotes(file).reasonBase, /stopped at page/);
  } finally { documents.extractDocumentText = realExtract; }
});

// ── #1871 review fixes ───────────────────────────────────────────────────────────────────────────

test('#1871: one sync spends at most its OCR budget across documents; the rest continue on a later sync', async () => {
  const ocr = fakeOcr(() => 'SYN-OCR');
  const budget = documents.ocrBudget({ PROJECT_SYNC_OCR_PAGES: '3' });
  assert.deepEqual(budget, { remaining: 3 });
  const deps = (b) => docling(fakeDocling({ total: 2, degraded: [1, 2] }), { ocrEnabled: true, extractPages: ocr.extractPages, ocrBudget: b });
  const a = await documents.extractDocumentText('a.pdf', syntheticPdf({ pages: 2 }), deps(budget));
  const b = await documents.extractDocumentText('b.pdf', syntheticPdf({ pages: 2 }), deps(budget));
  assert.equal(ocr.calls.reduce((n, c) => n + c.pages.length, 0), 3, 'three pages in all');
  assert.equal(budget.remaining, 0);
  assert.equal(a.completion, documents.COMPLETION);
  assert.equal(b.completion, undefined, 'b has a page left, so it stays open');
  assert.deepEqual(b.pageTexts.map((p) => p.retry?.outcome), ['recovered', undefined]);
  const c = await documents.extractDocumentText('c.pdf', syntheticPdf({ pages: 2 }), deps(budget));
  assert.equal(ocr.calls.reduce((n, x) => n + x.pages.length, 0), 3, 'an exhausted budget sends nothing');
  assert.equal(c.completion, undefined);
  // The next sync, a new budget: b finishes, and is not retried again after that.
  const next = await documents.completeDocument('b.pdf', Buffer.from('x'), b, deps(documents.ocrBudget({ PROJECT_SYNC_OCR_PAGES: '3' })));
  assert.deepEqual(next.pageTexts.map((p) => p.retry?.outcome), ['recovered', 'recovered']);
  assert.equal(next.completion, documents.COMPLETION);
  assert.equal(ocr.calls.reduce((n, x) => n + x.pages.length, 0), 4);
});

test('#1878: pages the OCR budget defers are logged as counts only, one line per document', async () => {
  const ocr = fakeOcr(() => 'SYN-OCR');
  const budget = documents.ocrBudget({ PROJECT_SYNC_OCR_PAGES: '3' });
  const deps = (b) => docling(fakeDocling({ total: 2, degraded: [1, 2] }), { ocrEnabled: true, extractPages: ocr.extractPages, ocrBudget: b });
  const lines = [];
  const orig = console.log; console.log = (...a) => lines.push(a.join(' '));
  const before = { ...documents.ocrDeferrals };
  try {
    await documents.extractDocumentText('QA-SYNTH-secret-a.pdf', syntheticPdf({ pages: 2 }), deps(budget));
    await documents.extractDocumentText('QA-SYNTH-secret-b.pdf', syntheticPdf({ pages: 2 }), deps(budget));
    await documents.extractDocumentText('QA-SYNTH-secret-c.pdf', syntheticPdf({ pages: 2 }), deps(budget));
  } finally { console.log = orig; }
  const mine = lines.filter((l) => l.includes('OCR budget deferred'));
  assert.equal(mine.length, 2, 'b (one page) and c (two pages) were deferred; a was not');
  assert.match(mine[0], /pagesDeferred=1 documentsDeferred=1 syncPagesDeferred=1 syncDocumentsDeferred=1/);
  assert.match(mine[1], /pagesDeferred=2 documentsDeferred=1 syncPagesDeferred=3 syncDocumentsDeferred=2/);
  for (const l of mine) assert.doesNotMatch(l, /QA-SYNTH|\.pdf|SYN-OCR/);
  assert.equal(documents.ocrDeferrals.pages - before.pages, 3);
  assert.equal(documents.ocrDeferrals.documents - before.documents, 2);
});

test('#1871: reading resumes after the highest page read, and a gap below it is a failed page', async () => {
  const pdf = syntheticPdf({ pages: 6 });
  const reader = countingReader();
  const stored = { text: '', pages: 6, state: 'partial', truncated: true, retryable: false,
    pageTexts: [1, 2, 4].map((n) => ({ number: n, text: `SYN-PAGE-${n}`, status: 'native', method: 'native' })) };
  const out = await documents.completeDocument('gap.pdf', pdf, stored, nativeOnly({ readPages: reader.readPages, env: {} }));
  assert.deepEqual(reader.calls, [{ first: 5, cap: 2 }]);
  assert.deepEqual(out.pageTexts.map((p) => [p.number, p.status]), [[1, 'native'], [2, 'native'], [3, 'failed'], [4, 'native'], [5, 'native'], [6, 'native']]);
  assert.equal(out.state, 'partial');
});

test('#1871: a range stopped by a busy worker is resumed at most RETRY_ATTEMPTS times, then the stop is stored', async () => {
  let asked = 0;
  const fake = fakeDocling({ total: 340 });
  const extractDocument = async (name, bytes, options) => {
    if (options?.pages) { asked++; throw Object.assign(new Error('Document extraction is busy; refresh to retry.'), { status: 503 }); }
    return fake.extractDocument(name, bytes, options);
  };
  const deps = docling(fake, { extractDocument });
  let out = await documents.extractDocumentText('long.pdf', syntheticPdf({ pages: 2 }), deps);
  assert.equal(out.completion, undefined);
  assert.equal(out.rangeAttempts, 1);
  for (let read = 0; read < 5; read++) out = await documents.completeDocument('long.pdf', Buffer.from('x'), out, deps);
  assert.equal(out.rangeAttempts, documents.RETRY_ATTEMPTS);
  assert.equal(out.completion, documents.COMPLETION);
  assert.deepEqual(out.stoppedAt, { page: 300, limit: 'error', error: 'Document extraction is busy; refresh to retry.' });
  assert.equal(asked, 3 * documents.RETRY_ATTEMPTS, 'three asks per attempt, three attempts');
});

test('#1871: large documents are read one at a time process-wide; small ones are not held up', async () => {
  let active = 0, most = 0, smallDone = false;
  const readPages = async (bytes, options) => {
    active++; most = Math.max(most, active);
    await new Promise((r) => setTimeout(r, 30));
    active--;
    return native.readInWorker(bytes, options);
  };
  const deps = nativeOnly({ readPages, env: { PROJECT_DOCUMENT_RANGE_PAGES: '30' } });
  const both = Promise.all([documents.extractDocumentText('a.pdf', big, deps), documents.extractDocumentText('b.pdf', big, deps)]);
  const small = documents.extractDocumentText('s.pdf', syntheticPdf({ pages: 1 }), nativeOnly({ env: {} })).then(() => { smallDone = true; });
  await small;
  const [a, b] = await both;
  assert.equal(most, 1, 'never two large reads at once');
  assert.ok(smallDone);
  assert.equal(a.state, 'ready'); assert.equal(b.state, 'ready');
});

test('#1871: a 90 MiB PDF read from storage and extracted peaks under 2x its size in RSS growth', async () => {
  const storage = require('./storage-client.cjs');
  const pdf = syntheticPdf({ pages: 60, padding: 90 * MiB });
  const realFetch = global.fetch;
  global.fetch = async () => new Response(new ReadableStream({
    // Views of the source, not copies: only the read itself should count.
    start(controller) { for (let at = 0; at < pdf.length; at += MiB) controller.enqueue(pdf.subarray(at, Math.min(pdf.length, at + MiB))); controller.close(); },
  }), { headers: { 'content-length': String(pdf.length) } });
  global.gc?.();
  const before = process.memoryUsage.rss();
  let peak = before;
  const watch = setInterval(() => { peak = Math.max(peak, process.memoryUsage.rss()); }, 10);
  let out;
  try {
    const conn = { kind: 's3', baseUrl: 'http://fixture.invalid', bucket: 'bucket', corpusRoot: '', username: '', secret: '' };
    const bytes = await storage.readBinaryFile(conn, 'big.pdf', { cap: 96 * MiB });
    assert.ok(bytes.buffer instanceof SharedArrayBuffer, 'a large read lands in shared memory');
    out = await documents.extractDocumentText('big.pdf', bytes, nativeOnly({ env: {} }));
  } finally { clearInterval(watch); global.fetch = realFetch; }
  const growth = (peak - before) / MiB, size = pdf.length / MiB;
  console.log(`[#1871 memory] ${size.toFixed(0)} MiB PDF read from storage, 60 pages in 3 ranges: peak RSS growth ${growth.toFixed(0)} MiB (${(growth / size).toFixed(2)}x)`);
  assert.equal(out.state, 'ready');
  assert.equal(out.pageTexts.length, 60);
  // Linux (DaServer, CI) maps an allocation this large fresh each time, so a range worker's full-length
  // pdf.js buffer stays unresident except for the chunks it reads. macOS's allocator re-zeroes a cached
  // large block on reuse, which makes every range after the first touch it all; there the bound is looser.
  const bound = process.platform === 'linux' ? 2 : 3.5;
  assert.ok(growth <= bound * size, `peak growth ${growth.toFixed(0)} MiB is within ${bound}x the ${size.toFixed(0)} MiB file`);
});
